package gameoflife;

import java.util.HashSet;
import java.util.Set;

public class GameOfLife {

    private static final int NEIGHBOURS_REQUIRED_TO_SURVIVE = 2;

    public Set<Cell> nextGeneration(Set<Cell> livingCells) {
        Set<Cell> survivors = new HashSet<>();
        for (Cell cell : livingCells) {
            if (survives(countLivingNeighbours(cell, livingCells))) {
                survivors.add(cell);
            }
        }
        return survivors;
    }

    private boolean survives(int livingNeighbours) {
        return livingNeighbours == NEIGHBOURS_REQUIRED_TO_SURVIVE;
    }

    private int countLivingNeighbours(Cell cell, Set<Cell> livingCells) {
        int count = 0;
        for (Cell neighbour : cell.neighbours()) {
            if (livingCells.contains(neighbour)) {
                count++;
            }
        }
        return count;
    }
}
EOF
